import{_ as l,l as r,o as i,c as n,v as e,p as s,x as t,d as m,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Diffusion-LM","description":"","frontmatter":{"title":"Diffusion-LM","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diffusion-lm.md","filePath":"llm/diffusion-lm.md","lastUpdated":1789023840000}'),E={name:"llm/diffusion-lm.md"};function _(h,a,f,x,u,c){const o=r("Mermaid");return i(),n("div",null,[a[1]||(a[1]=e('<h1 id="diffusion-lm" tabindex="-1">Diffusion-LM <a class="header-anchor" href="#diffusion-lm" aria-label="Permalink to &quot;Diffusion-LM&quot;">​</a></h1><div class="epigraph"><p>从高斯向量序列逐步去噪成词向量，中间连续潜变量让我们可以用梯度去同时满足流畅与控制。</p><footer>—— Li et al., Diffusion-LM Improves Controllable Text Generation, NeurIPS 2022</footer></div><p>自回归语言模型生成质量高，但控制往往要为每个约束微调，且左到右的顺序让句法树、填空、左右文同时成立这类全局约束很难修。Li、Thickstun、Gulrajani、Liang 与 Hashimoto 把连续扩散接到文本上：先把词嵌进连续空间，再对整句潜变量逐步去噪，最后圆整回词表。中间层 \\(x_T,\\ldots,x_0\\) 都可微，分类器或解析器的梯度可以直接打在潜变量上，语言模型本身冻结。这是连续扩散语言模型的早期完整方案，代码在 XiangLi1999/Diffusion-LM。后面的 <a href="/llm/sedd-diffusion-lm">SEDD</a>、<a href="/llm/mdlm">MDLM</a> 改走离散状态，控制故事不同，不要混成一篇。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>即插即用控制希望：\\(p(w\\mid c)\\propto p_{\\mathrm{lm}}(w)\\,p(c\\mid w)\\)。PPLM 在自回归隐状态上做梯度，只能影响「下一个词」，前面写错的结构难以回补，复杂句法几乎失败。FUDGE、GeDi 在每步词表上重加权，对情感、主题够用，对整句句法树或语义槽位不够。微调能学条件分布，却不能组合多个未一起训练的分类器，也不是即插即用。</p><p>文本是离散的，标准高斯扩散定义在 \\(\\mathbb{R}^d\\)。把词当成离散状态做吸收或均匀扩散，当时还没有后来 SEDD 那样能打 GPT-2 的似然。Diffusion-LM 的选择是：把离散序列嵌进连续空间，让视觉里已经成熟的去噪与梯度引导可以直接用。</p><h3 id="嵌入与圆整不是可选项" tabindex="-1">嵌入与圆整不是可选项 <a class="header-anchor" href="#嵌入与圆整不是可选项" aria-label="Permalink to &quot;嵌入与圆整不是可选项&quot;">​</a></h3><p>没有嵌入，就没有对 \\(x_0\\) 的高斯前向。没有圆整，\\(x_0\\) 落不回词。随机高斯嵌入或冻结的预训练词向量，在原文的初步实验里都弱于端到端学习嵌入。训练目标必须同时学扩散网络与 \\(\\mathrm{Emb}(\\cdot)\\)。圆整若只在最后一步 \\(\\mathrm{argmax}\\)，模型常常给出不肯贴住某个词向量的 \\(x_0\\)，解码发糊。</p><p><span class="marginnote">原文明确写：据他们所知这是连续扩散用于文本的首次完整探索。D3PM 一类离散扩散是相关工作，不是本方法的前向过程。评测主目标是可控生成成功率与教师 LM 的 lm-score，不是大规模困惑度竞赛；附录里固定单纯形嵌入对 held-out 困惑度更友好，与主文的生成质量叙事分开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前向在词 \\(w\\) 与 \\(x_0\\) 之间加一步 \\(q_\\phi(x_0\\mid w)=\\mathcal{N}(\\mathrm{Emb}(w),\\sigma_0 I)\\)，再按标准逐步加噪到 \\(x_T\\)。反向每步是高斯 \\(p_\\theta(x_{t-1}\\mid x_t)\\)，最后 \\(p_\\theta(w\\mid x_0)\\) 是逐位置 softmax。端到端 simplified 目标在 \\(\\mathcal{L}_{\\mathrm{simple}}\\) 之外加上 \\(\\|\\mathrm{Emb}(w)-\\mu_\\theta(x_1,1)\\|^2\\) 与圆整交叉熵，嵌入用重参数技巧反传。</p><p>为强调 \\(x_0\\) 必须贴住词向量，他们把逐步预测均值改成逐步预测 \\(x_0\\)：\\(f_\\theta(x_t,t)\\approx x_0\\)。解码时的夹紧技巧把 \\(f_\\theta\\) 先映射到最近的词嵌入再进入下一步噪声公式，减少中途漂移。网络是约 \\(80\\)M 的 Transformer，句长 \\(n=64\\)，扩散步 \\(T=2000\\)，平方根噪声日程。嵌入维在 E2E 上 \\(d=16\\)，在 ROCStories 上 \\(d=128\\)。E2E 约 \\(50\\)K 餐厅评论，ROCStories 约 \\(98\\)K 五句故事、词表约 \\(11\\)K。</p><h3 id="分类器引导在潜变量上走多步梯度" tabindex="-1">分类器引导在潜变量上走多步梯度 <a class="header-anchor" href="#分类器引导在潜变量上走多步梯度" aria-label="Permalink to &quot;分类器引导在潜变量上走多步梯度&quot;">​</a></h3><p>控制不直接改离散词，而分解为每步 \\(p(x_{t-1}\\mid x_t,c)\\propto p(x_{t-1}\\mid x_t)\\,p(c\\mid x_{t-1})\\)。分类器建在扩散潜变量上。更新是 \\(\\nabla_{x_{t-1}}\\log p(x_{t-1}\\mid x_t)+\\nabla_{x_{t-1}}\\log p(c\\mid x_{t-1})\\)，并加流畅正则 \\(\\lambda\\log p(x_{t-1}\\mid x_t)\\)。每步扩散做三次 Adagrad，步数从 \\(2000\\) 抽到 \\(200\\)。长度与填空可以不靠分类器：长度当分类器无关约束，填空用左右文锚定。需要单条高质量输出时，用 MBR 在样本集上按期望风险（如负 BLEU）挑一条。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连续层次潜变量让全局分类器——句法分析器、语义槽分类器——的梯度能同时碰到句中所有位置。自回归解码没有对称的「整句可微草稿」。组合控制就是把多个 \\(\\log p(c_i\\mid x_{t-1})\\) 加进同一梯度。六项任务覆盖语义内容、词性序列、句法树、句法跨度、长度、填空。相对先前即插即用，控制成功率几乎翻倍，并在分类器引导任务上赶上或超过为该任务微调的 GPT-2。填空上与从零训的自回归填空模型相当。解码 \\(200\\) 步仍比自回归慢约 \\(7\\) 倍；可控生成比 FUDGE 慢约 \\(1.5\\) 倍，比 PPLM 快约 \\(60\\) 倍。</p><p>学到的嵌入按词性成团，说明连续空间里句法角色有几何。夹紧把预测拉回词表流形，否则 \\(x_0\\)-参数化仍可能停在词与词之间。\\(\\lambda\\) 过大则控制失效，过小则句子不通；这是采样与最大化之间的折中，类似低温采样，不是另训一个条件 LM。</p><p><span class="marginnote">PPLM 基线在原文里只接到语义内容，因为其分类器没有位置信息，不能公平地打到词性或句法树。不要把「PPLM 没做句法」写成 PPLM 论文自己的主张。微调预言机（FT-sample / FT-search）不是即插即用，只提供上限。</span></p><h3 id="为什么后来离散扩散仍要另起炉灶" tabindex="-1">为什么后来离散扩散仍要另起炉灶 <a class="header-anchor" href="#为什么后来离散扩散仍要另起炉灶" aria-label="Permalink to &quot;为什么后来离散扩散仍要另起炉灶&quot;">​</a></h3><p>连续空间要圆整，似然与词表规模、嵌入几何纠缠，规模化到 GPT-2 级时被 SEDD、MDLM 用离散吸收过程超过。Diffusion-LM 的遗产是：非自回归草稿 + 可微中间态 + 梯度控制。离散方法用比率或掩码交叉熵做似然，用重掩码或概率速度做采样，控制接口变成「任意位置条件」而不是分类器反传。读 2022 年这篇，应把它当可控生成的连续解，而不是 2024 年离散扩散的实现说明书。</p>',20)),(i(),s(p,null,{default:t(()=>[d(o,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%A6%BB%E6%95%A3%E8%AF%8D%E5%BA%8F%E5%88%97%22%5D%20--%3E%20E%5B%22%E5%8F%AF%E5%AD%A6%E4%B9%A0%E5%B5%8C%E5%85%A5%20x0%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%89%8D%E5%90%91%E5%8A%A0%E5%99%AA%E8%87%B3%20xT%22%5D%0A%20%20XT%5B%22%E9%AB%98%E6%96%AF%20xT%22%5D%20--%3E%20DN%5B%22%E9%80%90%E6%AD%A5%E5%8E%BB%E5%99%AA%20f%CE%B8%22%5D%0A%20%20DN%20--%3E%20CL%5B%22%E5%8F%AF%E9%80%89%E5%A4%B9%E7%B4%A7%E5%88%B0%E6%9C%80%E8%BF%91%E8%AF%8D%22%5D%0A%20%20C%5B%22%E5%88%86%E7%B1%BB%E5%99%A8%20p(c%7Cx)%22%5D%20--%3E%20G%5B%22%E6%BD%9C%E5%8F%98%E9%87%8F%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20DN%20--%3E%20G%0A%20%20G%20--%3E%20X0%5B%22x0%22%5D%0A%20%20X0%20--%3E%20R%5B%22softmax%20%E5%9C%86%E6%95%B4%22%5D%0A%20%20R%20--%3E%20Y%5B%22%E5%8F%97%E6%8E%A7%E6%96%87%E6%9C%AC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>数据是 E2E 与 ROCStories，不是网页级预训练。句长 \\(64\\)、两千步扩散，服务延迟与自回归不在同一档。圆整误差、嵌入维度、噪声日程都敏感。复杂控制依赖分类器质量：句法树 F1 受分析器限制。组合控制成功，不表示任意多个分类器都能无损相加。</p><p>不要把 Diffusion-LM 写成「文本版 DDPM 直接把 one-hot 当连续向量」。前向从嵌入高斯开始。也不要把后来的掩码扩散目标写回这篇的 \\(\\mathcal{L}_{\\mathrm{simple}}\\)。教师 lm-score 用的是微调 GPT-2，因为生成含 UNK，对不上原版 GPT 词表。</p><p><span class="marginnote">出处：Xiang Lisa Li, John Thickstun, Ishaan Gulrajani, Percy Liang, Tatsunori B. Hashimoto，<em>Diffusion-LM Improves Controllable Text Generation</em>，NeurIPS 2022（arXiv:2205.14217）。连续扩散背景引用 Ho et al. 2020 与 Song et al.；即插即用对照含 PPLM 与 FUDGE。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Diffusion-LM 在词嵌入空间做连续扩散，用可学习嵌入与圆整把离散文本接到高斯去噪链上。</li><li>\\(x_0\\) 参数化与夹紧降低圆整误差；控制是对中间潜变量的带流畅正则的梯度更新。</li><li>六项细粒度控制上即插即用成功率大幅高于自回归基线，并可组合多个分类器。</li><li>代价是解码步数与似然规模化；后续离散扩散从另一条路追自回归困惑度。</li><li>评测集是 E2E 与 ROCStories，不是通用大模型。</li><li>出处：Li et al.，<em>Diffusion-LM Improves Controllable Text Generation</em>，NeurIPS 2022（arXiv:2205.14217）。</li></ul>',6))])}const P=l(E,[["render",_]]);export{A as __pageData,P as default};
